import {Worker} from 'node:worker_threads';
import {join} from 'node:path';
import {createHash} from 'node:crypto';
import type {Sheet,Profile} from './sheet';
// One job per server. Identical requests share work; generated bytes expire in memory.
let active:{key:string;promise:Promise<Buffer>}|undefined;
let cached:{key:string;bytes:Buffer;expires:number}|undefined;
export function renderPDF(sheet:Sheet,profile:Profile):Promise<Buffer>{
 const key=createHash('sha256').update(JSON.stringify({sheet,profile})).digest('hex');
 if(cached&&cached.expires>Date.now()&&cached.key===key)return Promise.resolve(cached.bytes);
 if(active)return active.key===key?active.promise:Promise.reject(new Error('PDF_BUSY'));
 const promise=new Promise<Buffer>((resolve,reject)=>{
  const worker=new Worker(join(process.cwd(),'.pdf-worker/worker.cjs'),{workerData:{sheet,profile},execArgv:[],resourceLimits:{maxOldGenerationSizeMb:160}});
  let settled=false;
  const finish=(error?:Error,bytes?:Buffer)=>{if(settled)return;settled=true;clearTimeout(timer);void worker.terminate().finally(()=>{if(error)reject(error);else resolve(bytes!);});};
  const timer=setTimeout(()=>finish(new Error('PDF_TIMEOUT')),35000);
  worker.once('message',(message:{error?:string;bytes?:Uint8Array})=>finish(message.error?new Error(message.error):undefined,message.bytes?Buffer.from(message.bytes):undefined));
  worker.once('error',()=>finish(new Error('PDF_WORKER_FAILED')));
  worker.once('exit',()=>{if(!settled)finish(new Error('PDF_WORKER_EXIT'));});
 }).then(bytes=>{if(bytes.length<2*1024*1024){const value={key,bytes,expires:Date.now()+120000};cached=value;const timer=setTimeout(()=>{if(cached===value)cached=undefined;},120000);timer.unref();}return bytes;}).finally(()=>{active=undefined;});
 active={key,promise};return promise;
}
